import{_ as n,l as r,o as e,c as i,v as l,p as s,x as o,d as p,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"增长核算对发展核算","description":"","frontmatter":{"title":"增长核算对发展核算","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/growth-vs-development-acct.md","filePath":"econ/growth-vs-development-acct.md","lastUpdated":1789023840000}'),E={name:"econ/growth-vs-development-acct.md"};function h(d,a,P,B,C,m){const t=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=l('<h1 id="增长核算对发展核算" tabindex="-1">增长核算对发展核算 <a class="header-anchor" href="#增长核算对发展核算" aria-label="Permalink to &quot;增长核算对发展核算&quot;">​</a></h1><div class="epigraph"><p>同一套生产函数，对时间差分得到增长率的贡献，对截面取比得到水平差异的贡献；两个问题不要共用同一句「全是 TFP」。</p><footer>—— Caselli, Accounting for Cross-Country Income Differences, Handbook of Economic Growth, 2005；对照 Hall and Jones, QJE 1999</footer></div><p><a href="/econ/convergence-accounting">上一课</a>已经用 Hall–Jones 一类分解把 \\(Y/L\\) 拆成资本强度、\\(h\\) 与剩余 \\(A\\)，并分清绝对/条件收敛。本课的缺口不是再做一遍收敛回归，而是把<strong>增长核算</strong>（一国沿时间）与<strong>发展核算</strong>（各国在某一时点的水平）对起来：公式同源，问题、样本与常见结论不同。货币课从下一课开始；增长主干用这一对照收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛残差课写的是 \\(\\Delta\\ln Y=\\alpha\\Delta\\ln K+(1-\\alpha)\\Delta\\ln L+\\Delta\\ln A\\)，问增长有多快、各贡献多少。发展核算问的是：美国与某穷国的 \\(Y/L\\) <strong>水平</strong>差，有多少来自 \\(K\\)、多少来自 \\(h\\)、多少来自 \\(A\\)。把东亚「增长很快」的增长核算结论，直接说成「穷国落后是因为不会积累 \\(K\\)」，是把时间斜率当成截面水平。Caselli（2005）把发展核算写成系统账户：在观测到的 \\(K\\)、\\(h\\) 下，反事实效率能解释多少收入比。缺口是分清这两种会计，而不是再检验 \\(\\beta\\) 收敛。</p><p><span class="marginnote">增长核算可以是「这段时间主要靠资本积累」；发展核算仍可以是「国与国之间主要靠 \\(A\\)」。两者同时成立，因为比较的对象不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>增长核算：对同一经济的相邻年（或长期平均）做 Solow 1957 的差分。发展核算：对同一年的多国，用</p> \\[\\frac{Y}{L}=A\\cdot\\Bigl(\\frac{K}{Y}\\Bigr)^{\\alpha/(1-\\alpha)}h \\]<p>一类水平分解（写法随 Caselli、Hall–Jones 而异），比较 \\(\\ln(Y/L)\\) 的跨国方差中 \\(A\\) 与要素的份额。资本用 \\(K/Y\\) 而非 \\(K/L\\)，是为了减轻内生性：穷国 \\(K/L\\) 低，部分正因为 \\(A\\) 低。Hall–Jones 强调制度进入 \\(A\\)；Caselli 强调核算对函数形式与测量的敏感。</p>',10)),(e(),s(A,null,{default:o(()=>[c(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAME%5B%22%E5%90%8C%E4%B8%80%E7%94%9F%E4%BA%A7%E5%87%BD%E6%95%B0%22%5D%20--%3E%20GACC%5B%22%E5%A2%9E%E9%95%BF%E6%A0%B8%E7%AE%97%EF%BC%9A%E6%97%B6%E9%97%B4%E5%B7%AE%E5%88%86%22%5D%0A%20%20SAME%20--%3E%20DACC%5B%22%E5%8F%91%E5%B1%95%E6%A0%B8%E7%AE%97%EF%BC%9A%E6%88%AA%E9%9D%A2%E6%B0%B4%E5%B9%B3%22%5D%0A%20%20GACC%20--%3E%20RATE%5B%22%E8%B0%81%E8%B4%A1%E7%8C%AE%E4%BA%86%E5%A2%9E%E9%95%BF%E7%8E%87%22%5D%0A%20%20DACC%20--%3E%20LEVEL%5B%22%E8%B0%81%E8%B4%A1%E7%8C%AE%E4%BA%86%E6%94%B6%E5%85%A5%E6%AF%94%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>收敛回归问的是增长率对初始水平的斜率，既不是增长核算的贡献分解，也不是发展核算的水平方差分解。三句话不要焊成一句「索洛被证实」。</p><h3 id="ppp-不是-cip" tabindex="-1">PPP 不是 CIP <a class="header-anchor" href="#ppp-不是-cip" aria-label="Permalink to &quot;PPP 不是 CIP&quot;">​</a></h3><p>截面比较必须用购买力平价把 \\(Y\\) 与 \\(K\\) 放到可比物量。那是篮子问题，回到价格指数与 <a href="/econ/ppp-loop">PPP</a>。外汇市场上的抛补利率平价是资产价格，实证在<a href="/quant/irp">量化栏</a>，不在本课当发展核算。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>时间上，\\(K\\) 可以快速积累，\\(A\\) 的年变化往往较小，于是高增长时段的增长核算常显示资本贡献大。截面上，\\(K/Y\\) 跨国差有限（收入法份额相近时），\\(Y/L\\) 的巨大差距就落到 \\(A\\) 与 \\(h\\) 上——Hall–Jones、Caselli 的典型叙述。错配课说明 \\(A\\) 的水平差含楔子；内生增长说明 \\(A\\) 的长期变化可以来自研发。核算不识别因果：它只禁止用错会计对象。</p><p>若平减、住房与政府产出口径不一致，发展核算的 \\(A\\) 会被价格指数污染。链式物量适合一国的时间序列；跨国水平更依赖 ICP 一类基准年篮子。两种指数回答不同问题，与<a href="/econ/chain-index-bias">链式指数</a>课同一警告。</p><p>错配课已经说明截面 \\(A\\) 含楔子。因此发展核算里「TFP 为主」不必读成「穷国不会发明」，也可以读成「要素没按边际产出对齐」。增长核算里一段时期的高 TFP 增长，同样可以是去扭曲而不是发明。Caselli 的敏感度实验（改 \\(\\alpha\\)、改 \\(h\\) 的构造）改变的是份额，不取消这两种会计对象的区别。</p><p>收敛是第三套句子：条件收敛说参数相同则水平差缩小，不告诉你差的是 \\(K\\) 还是 \\(A\\)。把 \\(\\beta\\) 收敛回归的斜率当成发展核算的 \\(A\\) 份额，是把增长率对初始水平的相关写成水平分解。</p><p><span class="marginnote">「要素足够解释」还是「TFP 为主」随 \\(\\alpha\\)、折旧、\\(h\\) 的构造而变。Caselli 的贡献是展示这条敏感度，不是宣布某一个百分比为定律。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重估 Hall–Jones 表中的数字，不把殖民与地理的 IV 争论搬进来。增长回归的政策含义仍要等卢卡斯批判。也不要把人均 GDP 差写成交易价差。货币中性下一课建立在已经有 \\(y^*\\) 的世界上：那个 \\(y^*\\) 的水平由本课这类账户说明，短期缺口用 \\(u\\) 与 \\(y-y^*\\)。</p><p>后课默认：谈「这段时期为何增长」用增长核算；谈「为何各国贫富悬殊」用发展核算；\\(A\\) 在两套账里都是残差。下一课换对象：支付手段与货币层次。增长主干到此收束，不再从索洛运动方程重起。错配与内生技术都进入这个 \\(A\\)，核算不替你选按钮。</p><p>PPP 篮子用于截面物量，不要用市场汇率把水平差写成价差。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>增长核算分解增长率；发展核算分解水平比；公式同源、问题不同。</li><li>时间上资本贡献可以很大，截面上剩余 \\(A\\) 仍可主导——并不矛盾。</li><li>收敛回归是第三句，不是这两种会计的替代。</li><li>PPP 篮子用于截面物量；CIP 不在本栏。</li><li>出处：Caselli, Handbook 2005；Hall and Jones, QJE 1999；Solow 1957。</li></ul>',15))])}const u=n(E,[["render",h]]);export{f as __pageData,u as default};
